#include <sys/socket.h>
#include <linux/netlink.h>
#include <linux/rtnetlink.h>
#include <linux/pkt_sched.h>
#include <string.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <net/if.h>

#define TCA_KIND 1

int main() {
    int s = socket(AF_NETLINK, SOCK_RAW, NETLINK_ROUTE);
    if (s < 0) { perror("socket"); return 1; }

    unsigned int ifindex = if_nametoindex("lo");
    if (ifindex == 0) { perror("if_nametoindex"); return 1; }

    struct {
        struct nlmsghdr nlh;
        struct tcmsg tcm;
        char attrbuf[1024];
    } msg;

    // 1. Add hfsc
    memset(&msg, 0, sizeof(msg));
    msg.nlh.nlmsg_len = NLMSG_LENGTH(sizeof(struct tcmsg));
    msg.nlh.nlmsg_type = RTM_NEWQDISC;
    msg.nlh.nlmsg_flags = NLM_F_REQUEST | NLM_F_CREATE | NLM_F_EXCL;
    msg.nlh.nlmsg_seq = 1;

    msg.tcm.tcm_family = AF_UNSPEC;
    msg.tcm.tcm_ifindex = ifindex;
    msg.tcm.tcm_handle = 0x10000; // 1:0
    msg.tcm.tcm_parent = TC_H_ROOT;

    struct nlattr *na = (struct nlattr *)msg.attrbuf;
    na->nla_type = TCA_KIND;
    int kind_len = strlen("hfsc") + 1;
    na->nla_len = NLA_ALIGN(sizeof(struct nlattr) + kind_len);
    strcpy((char *)((void *)na + sizeof(struct nlattr)), "hfsc");
    msg.nlh.nlmsg_len += na->nla_len;

    if (send(s, &msg, msg.nlh.nlmsg_len, 0) < 0) {
        perror("sendmsg 1 hfsc"); 
        // Proceed even if it fails (it might ideally exist)
    }

    // 2. Add fq_codel to a non-existent class of hfsc.
    // HFSC is at 1:0.
    // Lets try to add to parent 1:1. 1:1 does not exist.

    memset(&msg, 0, sizeof(msg));
    msg.nlh.nlmsg_len = NLMSG_LENGTH(sizeof(struct tcmsg));
    msg.nlh.nlmsg_type = RTM_NEWQDISC;
    msg.nlh.nlmsg_flags = NLM_F_REQUEST | NLM_F_CREATE; // | NLM_F_EXCL;
    msg.nlh.nlmsg_seq = 2;

    msg.tcm.tcm_family = AF_UNSPEC;
    msg.tcm.tcm_ifindex = ifindex;
    msg.tcm.tcm_handle = 0; 
    msg.tcm.tcm_parent = 0x10001; // 1:1

    na = (struct nlattr *)msg.attrbuf;
    na->nla_type = TCA_KIND;
    kind_len = strlen("fq_codel") + 1;
    na->nla_len = NLA_ALIGN(sizeof(struct nlattr) + kind_len);
    strcpy((char *)((void *)na + sizeof(struct nlattr)), "fq_codel");
    msg.nlh.nlmsg_len += na->nla_len;

    if (send(s, &msg, msg.nlh.nlmsg_len, 0) < 0) {
        perror("sendmsg 2 fq_codel");
    }

    return 0;
}

